1	package meter
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 本文件回归“取消订阅、终止后重新开通不清除账户内旧付款标识与首次登记结果”。
9	//
10	// 付款标识只在所属账户内去重，付款记录保存在账户维度：按月取消让旧订阅在
11	// 三月月初实际终止、随后用同一 Subscribe 入口开通另一套餐，不能清掉旧订阅
12	// 期间登记的付款，也不能改动首次登记完成时保存的历史结果（BillBalance、
13	// Settled）。正常的分次付款与按月取消行为必须同时保留。
14	//
15	// 时间线（全部 UTC）：
16	//
17	//	2026-01-01 开通套餐 plan1200：月费 1200，无税、无超额。
18	//	2026-02-01 为 2026-01 出账：应付 1200；先用付款标识 pay-old 登记 500，
19	//	           首次结果为实际登记、余额 700、尚未付清。
20	//	2026-02-15 登记按月取消，2026-03-01 00:00 实际终止（二月仍按完整月计费）。
21	//	2026-03-01 重新开通月费 2400 的另一套餐 plan2400（无税、无超额）。
22	//	           重新开通后用另一标识补齐一月剩余 700，一月账单结清。
23	//	           此后原样重报 pay-old 的 500：Registered=false，付款仍属于
24	//	           原账户的一月账单，BillBalance=700、Settled=false 是首次登记
25	//	           完成时的结果，不随后来结清而变化，也不再次增加已付金额。
26	//	2026-04-01 为 2026-03 出账：应付 2400。旧标识改金额（501）或改指向三月
27	//	           账期始终是 ErrPaymentConflict——即使三月账单尚未生成，也不能
28	//	           改报成账单不存在；冲突不改动两张账单与原付款结果。未使用过的
29	//	           新标识登记三月 500 分正常成功，一月保持结清。
30	
31	// paymentResubscribeFixture 搭好账户与两份套餐：plan1200 一月已开通，
32	// 时钟停在 2026-02-01 00:00（一月账期恰好结束）。
33	func paymentResubscribeFixture(t *testing.T) (*Service, *fakeClock) {
34		t.Helper()
35		s, clk := newTestService(utc(2026, 1, 1, 0, 0))
36		mustPlan(t, s, Plan{ID: "plan1200", MonthlyFee: 1200, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
37		mustPlan(t, s, Plan{ID: "plan2400", MonthlyFee: 2400, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
38		mustAccount(t, s, "u")
39		mustSubscribe(t, s, "u", "plan1200", utc(2026, 1, 1, 0, 0))
40	
41		clk.t = utc(2026, 2, 1, 0, 0)
42		return s, clk
43	}
44	
45	// wantBillPaymentState 校验指定账单的当前付款状态，并保证应付总额不被付款、
46	// 重报或重新开通改动。
47	func wantBillPaymentState(t *testing.T, s *Service, period Month, totalDue, paid, balance int64, settled bool) Bill {
48		t.Helper()
49		b, err := s.GetBill("u", period)
50		if err != nil {
51			t.Fatalf("get bill %s: %v", period, err)
52		}
53		if b.TotalDue != totalDue || b.Paid != paid || b.Balance != balance || b.Settled != settled {
54			t.Fatalf("bill %s state: due=%d paid=%d balance=%d settled=%v, want due=%d paid=%d balance=%d settled=%v",
55				period, b.TotalDue, b.Paid, b.Balance, b.Settled, totalDue, paid, balance, settled)
56		}
57		return b
58	}
59	
60	// TestPaymentHistorySurvivesCancelResubscribe 端到端回归：同一账户取消旧订阅、
61	// 终止后重新开通另一套餐，旧付款标识与首次登记结果必须原样保留。
62	func TestPaymentHistorySurvivesCancelResubscribe(t *testing.T) {
63		s, clk := paymentResubscribeFixture(t)
64	
65		plan1200Terms := termsOf(Plan{ID: "plan1200", MonthlyFee: 1200})
66		plan2400Terms := termsOf(Plan{ID: "plan2400", MonthlyFee: 2400})
67	
68		// 一月账单应付 1200：无超额、无税。
69		janBill, err := s.CreateBill("u", jan(2026))
70		if err != nil {
71			t.Fatalf("create jan bill: %v", err)
72		}
73		if janBill.TotalDue != 1200 || janBill.Paid != 0 || janBill.Balance != 1200 || janBill.Settled {
74			t.Fatalf("jan bill initial state: %+v", janBill)
75		}
76	
77		// 分次付款第一笔：pay-old 登记 500，首次实际登记，余额 700，未付清。
78		first, err := s.RecordPayment("u", "pay-old", jan(2026), 500)
79		if err != nil {
80			t.Fatalf("first payment 500: %v", err)
81		}
82		if !first.Registered || first.Payment.AccountID != "u" || first.Payment.PaymentID != "pay-old" ||
83			first.Payment.Period != jan(2026) || first.Payment.Amount != 500 {
84			t.Fatalf("first payment content/registered: %+v", first)
85		}
86		if first.BillBalance != 700 || first.Settled {
87			t.Fatalf("first payment result: balance=%d settled=%v, want 700/false",
88				first.BillBalance, first.Settled)
89		}
90		wantBillPaymentState(t, s, jan(2026), 1200, 500, 700, false)
91	
92		// 二月中旬登记按月取消：终止时刻为三月月初零点，当月仍按完整月计费。
93		clk.t = utc(2026, 2, 15, 12, 0)
94		cancelRes := mustCancel(t, s, "u")
95		if !cancelRes.Cancelled || !cancelRes.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
96			t.Fatalf("cancel result = %+v, want end 2026-03-01", cancelRes)
97		}
98	
99		// 三月月初终止已实际发生：无有效订阅、无待取消时刻；历史账单继续可查，
100		// 旧付款结果此刻也仍然保留。
101		clk.t = utc(2026, 3, 1, 0, 0)
102		gapStatus, err := s.Status("u")
103		if err != nil {
104			t.Fatalf("status at termination: %v", err)
105		}
106		if gapStatus.Subscribed || gapStatus.ScheduledEnd != nil || gapStatus.CurrentTerms != (PlanTerms{}) {
107			t.Fatalf("status after termination: %+v", gapStatus)
108		}
109		wantBillPaymentState(t, s, jan(2026), 1200, 500, 700, false)
110	
111		// 同一入口重新开通月费 2400 的另一套餐：新订阅保存自己的开通快照。
112		mustSubscribe(t, s, "u", "plan2400", utc(2026, 3, 1, 0, 0))
113		st, err := s.Status("u")
114		if err != nil {
115			t.Fatalf("status after resubscribe: %v", err)
116		}
117		if !st.Subscribed || st.CurrentTerms != plan2400Terms {
118			t.Fatalf("current terms after resubscribe = %+v, want plan2400", st.CurrentTerms)
119		}
120	
121		// 重新开通后用另一标识补齐一月剩余 700：分次付款的第二笔正常登记并结清。
122		rest, err := s.RecordPayment("u", "pay-rest", jan(2026), 700)
123		if err != nil {
124			t.Fatalf("pay remaining 700 after resubscribe: %v", err)
125		}
126		if !rest.Registered || rest.Payment.PaymentID != "pay-rest" || rest.Payment.Amount != 700 ||
127			rest.BillBalance != 0 || !rest.Settled {
128			t.Fatalf("remaining payment result: %+v", rest)
129		}
130	
131		// 原样重报最早的 500：成功但本次不再登记；付款仍属于原账户的一月账单。
132		// BillBalance=700、Settled=false 是首次登记完成时的历史结果，不能改成
133		// 后来结清时的 0/true，也不能再次增加已付金额。
134		replay, err := s.RecordPayment("u", "pay-old", jan(2026), 500)
135		if err != nil {
136			t.Fatalf("verbatim replay after settle: %v", err)
137		}
138		if replay.Registered {
139			t.Fatalf("replay must not register again: %+v", replay)
140		}
141		if replay.Payment != (Payment{AccountID: "u", PaymentID: "pay-old", Period: jan(2026), Amount: 500}) {
142			t.Fatalf("replay payment content changed: %+v", replay.Payment)
143		}
144		if replay.BillBalance != 700 || replay.Settled {
145			t.Fatalf("replay historical result: balance=%d settled=%v, want first-time 700/false",
146				replay.BillBalance, replay.Settled)
147		}
148	
149		// 一月账单当前状态：累计已付 1200、余额为零、已经付清；应付仍是旧套餐
150		// 的 1200，条款仍是旧套餐快照，不受新套餐影响。
151		janNow := wantBillPaymentState(t, s, jan(2026), 1200, 1200, 0, true)
152		if janNow.Terms != plan1200Terms {
153			t.Fatalf("jan bill terms = %+v, want plan1200 snapshot", janNow.Terms)
154		}
155	
156		// Status 的账单摘要与 GetBill 同源，反映查询时点：一月已付 1200、结清。
157		// 重报不能把已结清账单恢复成欠款；当前生效套餐仍是重新开通的 plan2400。
158		st, err = s.Status("u")
159		if err != nil {
160			t.Fatalf("status after replay: %v", err)
161		}
162		if !st.Subscribed || st.CurrentTerms != plan2400Terms {
163			t.Fatalf("current terms changed by replay: %+v", st.CurrentTerms)
164		}
165		if st.Suspended {
166			t.Fatalf("settled account must not be suspended: %+v", st.Bills)
167		}
168		if len(st.Bills) != 1 || st.Bills[0].Period != jan(2026) ||
169			st.Bills[0].TotalDue != 1200 || st.Bills[0].Paid != 1200 ||
170			st.Bills[0].Balance != 0 || !st.Bills[0].Settled {
171			t.Fatalf("status jan summary after replay: %+v", st.Bills)
172		}
173	
174		// 旧标识不能拿来登记新付款：保持一月账期但金额改成 501，冲突。
175		if _, err := s.RecordPayment("u", "pay-old", jan(2026), 501); !errors.Is(err, ErrPaymentConflict) {
176			t.Fatalf("old id with changed amount: %v", err)
177		}
178		// 保持 500 但改指向三月账期：同样冲突。此时三月尚未出账，
179		// 也不能改报成 ErrBillNotFound。
180		if _, err := s.RecordPayment("u", "pay-old", mar(2026), 500); !errors.Is(err, ErrPaymentConflict) {
181			t.Fatalf("old id repointed to unbilled march: %v", err)
182		} else if errors.Is(err, ErrBillNotFound) {
183			t.Fatalf("old id repointed to unbilled march must be conflict, got bill not found")
184		}
185	
186		// 冲突不消耗标识、不改数据：原样重报仍返回首次结果，一月仍结清，
187		// 重新开通生效的套餐不变。
188		replay2, err := s.RecordPayment("u", "pay-old", jan(2026), 500)
189		if err != nil || replay2.Registered || replay2.BillBalance != 700 || replay2.Settled {
190			t.Fatalf("replay after conflicts: %+v %v", replay2, err)
191		}
192		wantBillPaymentState(t, s, jan(2026), 1200, 1200, 0, true)
193	
194		// 四月月初为三月出账：按重新开通的 plan2400 计 2400，一月金额不受影响。
195		clk.t = utc(2026, 4, 1, 0, 0)
196		marBill, err := s.CreateBill("u", mar(2026))
197		if err != nil {
198			t.Fatalf("create march bill: %v", err)
199		}
200		if marBill.TotalDue != 2400 || marBill.Paid != 0 || marBill.Balance != 2400 || marBill.Settled {
201			t.Fatalf("march bill initial state: %+v", marBill)
